import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernel for fused batch norm + mean subtraction
fused_op_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_bn_mean_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int N, int C, int D, int H, int W,
    float eps
) {
    extern __shared__ float shared[];

    int n = blockIdx.y;
    int c = blockIdx.x;

    if (n >= N || c >= C) return;

    int spatial_size = D * H * W;
    int tid = threadIdx.x;
    int stride = blockDim.x;

    // Compute mean
    float mean = 0.0f;
    for (int i = tid; i < spatial_size; i += stride) {
        int offset = ((n * C + c) * D * H * W) + i;
        mean += input[offset];
    }
    mean = block_reduce_sum(mean, shared) / spatial_size;

    // Compute variance
    __syncthreads();
    float var = 0.0f;
    for (int i = tid; i < spatial_size; i += stride) {
        int offset = ((n * C + c) * D * H * W) + i;
        float diff = input[offset] - mean;
        var += diff * diff;
    }
    var = block_reduce_sum(var, shared) / spatial_size;

    // Apply batch norm and subtract mean
    float inv_std = rsqrtf(var + eps);
    float gamma = weight[c];
    float beta = bias[c];

    for (int i = tid; i < spatial_size; i += stride) {
        int offset = ((n * C + c) * D * H * W) + i;
        float val = (input[offset] - mean) * inv_std;
        output[offset] = gamma * val + beta - mean;
    }
}

__device__ float block_reduce_sum(float val, float* shared) {
    int tid = threadIdx.x;
    shared[tid] = val;
    __syncthreads();

    for (int s = blockDim.x/2; s > 0; s >>= 1) {
        if (tid < s) {
            shared[tid] += shared[tid + s];
        }
        __syncthreads();
    }
    return shared[0];
}

torch::Tensor fused_op_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int D, int H, int W,
    float eps
) {
    auto N = input.size(0);
    auto C = input.size(1);
    auto output = torch::empty_like(input);

    dim3 blocks(C, N);
    int threads = 256;
    size_t shared_size = threads * sizeof(float);

    fused_bn_mean_kernel<<<blocks, threads, shared_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, D, H, W,
        eps
    );

    return output;
}
"""

fused_op_cpp = "torch::Tensor fused_op_cuda(torch::Tensor, torch::Tensor, torch::Tensor, int, int, int, float);"

fused_op_ext = load_inline(
    name="fused_op",
    cpp_sources=fused_op_cpp,
    cuda_sources=fused_op_source,
    functions=["fused_op_cuda"],
    verbose=True,
    extra_cflags=["-O3"],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, bias=True):
        super().__init__()
        self.conv_transpose = nn.ConvTranspose3d(
            in_channels, out_channels, kernel_size,
            stride=stride, padding=padding, bias=bias
        )
        self.bn_weight = nn.Parameter(torch.ones(out_channels))
        self.bn_bias = nn.Parameter(torch.zeros(out_channels))
        self.eps = 1e-5

    def forward(self, x):
        x = self.conv_transpose(x)
        D, H, W = x.shape[2:]
        x = fused_op_ext.fused_op_cuda(
            x, self.bn_weight, self.bn_bias,
            D, H, W, self.eps
        )
        return x
